INSERT INTO tasks VALUES('t-read-contracts','p-stoc',NULL,0,'Read repo contracts','Read the repo instructions and core docs required by AGENTS.md before implementation. Produce working constraints for chief-fs: workspace style, docs requirements, axioms that affect filesystem design, and known risks/open questions. Acceptance: relevant constraints are recorded with plandb context and the task is complete before code edits.','done','generic',0,'contracts','2026-04-22 02:22:22','2026-04-22 02:22:22','2026-04-22 02:23:14','{"summary":"Read core docs plus ADR-0006 and FS research; recorded Chief FS constraints."}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:22:22',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:13','2026-04-22 02:23:14');
INSERT INTO tasks VALUES('t-inspect-workspace','p-stoc',NULL,0,'Inspect Rust workspace patterns','Inspect root Cargo.toml and existing prototype crates to match workspace/package style, Rust edition, dependency conventions, test patterns, and lint expectations. Acceptance: crate scaffold decisions are known and recorded before creating prototypes/chief-fs.','done','generic',0,'workspace','2026-04-22 02:22:22','2026-04-22 02:22:22','2026-04-22 02:23:14','{"summary":"Inspected workspace Cargo.toml and prototype crate conventions; recorded Rust workspace constraints."}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:22:22',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:19','2026-04-22 02:23:14');
INSERT INTO tasks VALUES('t-scaffold-crate','p-stoc',NULL,0,'Scaffold chief-fs crate','Create prototypes/chief-fs as a complete Rust crate, add it to root Cargo.toml workspace members, and set dependencies requested by the user including Linux-only fuser. Acceptance: Cargo metadata can see package chief-fs and the crate has src/tests/docs file placeholders ready for implementation.','done','generic',0,'codex-chief-fs','2026-04-22 02:23:21','2026-04-22 02:23:21','2026-04-22 02:23:53','{"summary":"Created prototypes/chief-fs crate, source/test/doc placeholders, and added workspace member."}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:23:21',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:26','2026-04-22 02:23:53');
INSERT INTO tasks VALUES('t-implement-cas','p-stoc',NULL,0,'Implement CAS store','Implement src/cas.rs with a blake3 content-addressed append-only blob store. Store blobs at /cas/<aa>/<bb>/<CID>, expose put/get/stat operations, validate deterministic CID behavior, and avoid overwriting existing content. Acceptance: API is testable and returns blob metadata without platform-specific dependencies.','done','generic',0,'cas-local','2026-04-22 02:24:10','2026-04-22 02:24:10','2026-04-22 02:27:03','{"summary":"Implemented blake3 CAS store with put/get/stat/path helpers and CHIEF_HOME/cas shard layout."}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:24:10',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:32','2026-04-22 02:27:03');
INSERT INTO tasks VALUES('t-implement-aliases','p-stoc',NULL,0,'Implement alias sidecar','Implement src/aliases.rs with a rusqlite SQLite sidecar mapping logical paths to CIDs. Support set/get/delete/rename/list operations, preserve CAS blobs on alias deletes, and make rename preserve the CID while updating paths. Acceptance: deterministic, transaction-safe alias behavior with tests covering rename semantics.','done','generic',0,'default','2026-04-22 02:24:14','2026-04-22 02:24:14','2026-04-22 02:26:11',NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:24:14',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:37','2026-04-22 02:26:11');
INSERT INTO tasks VALUES('t-implement-cli','p-stoc',NULL,0,'Implement CLI','Implement src/main.rs exposing put, get, mount, and capture commands with manual argument parsing. Wire commands to CAS, alias sidecar, Linux FUSE shim, and capture daemon. Acceptance: CLI has helpful usage/errors and builds without clap on macOS and Linux.','running','generic',0,'cli-local','2026-04-22 02:27:39','2026-04-22 02:27:39',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:27:39',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:43','2026-04-22 02:27:39');
INSERT INTO tasks VALUES('t-implement-platform','p-stoc',NULL,0,'Implement platform shims','Implement src/fuse_shim.rs as Linux-only read-only FUSE mirror using fuser behind cfg(target_os = "linux"), with a non-Linux stub returning a clear error. Implement src/capture_daemon.rs with Linux capture behavior for user-declared directories and a macOS FSEvents stub that compiles. Acceptance: cargo build works on macOS without fuser and Linux has feature-complete mount/capture entry points.','running','generic',0,'platform-worker','2026-04-22 02:27:44','2026-04-22 02:27:44',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-22 02:27:44',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:51','2026-04-22 02:27:44');
INSERT INTO tasks VALUES('t-write-tests','p-stoc',NULL,0,'Write integration tests','Create tests/integration.rs covering CAS roundtrip, deterministic same-content CIDs, alias rename preserving CID, and capture throughput. Gate Linux-specific FUSE/capture expectations with cfg(target_os = "linux") and keep cross-platform CAS/alias tests active. Acceptance: cargo test -p chief-fs passes locally.','pending','generic',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:21:56','2026-04-22 02:21:56');
INSERT INTO tasks VALUES('t-document-prototype','p-stoc',NULL,0,'Document chief-fs','Create prototypes/chief-fs/README.md with roughly 40 lines covering overview, usage, storage layout, FUSE/capture behavior, and limitations. Create measurements.md with performance report from local test runs and note platform constraints. Acceptance: both docs are present and accurate to implemented behavior.','pending','generic',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-22 02:22:01','2026-04-22 02:22:01');
