INSERT INTO learnings VALUES('c-trxg','p-stoc','t-read-contracts','contracts','discovery','Chief FS constraints: accepted ADR-0006 defines BLAKE3 CAS plus FUSE human-folder shim; CIDs must survive rename/move; deletes/tombstones preserve CAS blobs; capture daemon hashes writes, updates alias/index, and eventually emits provenance events. Prototype should stay local-first and boring below L2.','2026-04-22 02:23:03');
INSERT INTO learnings VALUES('c-pglj','p-stoc','t-inspect-workspace','workspace','discovery','Rust workspace patterns: root workspace resolver=2, edition 2021, rust-version 1.75; prototypes are workspace members with package-local Cargo.toml, src/lib.rs for libraries, tests/ for integration. Workspace deps include blake3, tokio, anyhow, serde, rusqlite bundled, chrono, tempfile; uuid is used by chief-inference but not yet workspace-level.','2026-04-22 02:23:08');
INSERT INTO learnings VALUES('c-ojmb','p-stoc','t-implement-aliases','default','blocker','Implemented SQLite-backed alias store in prototypes/chief-fs/src/aliases.rs. cargo test -p chief-fs could not complete in this environment because dependency resolution needs crates.io access and offline mode reports missing fuser for chief-fs.','2026-04-22 02:26:11');
INSERT INTO learnings VALUES('c-jz55','p-stoc','t-implement-cas','cas-local','discovery','CAS implementation uses BLAKE3 lowercase hex CIDs and stores blobs under CHIEF_HOME/cas/aa/bb/cid. put_bytes writes via same-directory temp file + hard link publish, so existing blobs are not overwritten and duplicate content resolves to the existing blob.','2026-04-22 02:26:55');
INSERT INTO learnings VALUES('c-7x5j','p-stoc',NULL,'default','discovery','chief-fs prototype will keep alias store at chief_home/aliases.sqlite and CAS at chief_home/cas, with capture_paths doing a recursive one-shot ingest of declared directories for v0 while fanotify/FSEvents remain platform-specific shims.','2026-04-22 02:28:27');
